// Sample listing, shaped exactly like Discourse's /c/jobs/13.json response.
//
// Lets the whole workflow be run and judged with no network and no account.
// Four topics, chosen to exercise every branch: one ordinary hiring post, one
// that is already three days old, one pinned announcement, and one freelancer
// advertising himself.

const minutesAgo = m => new Date(Date.now() - m * 60000).toISOString();

return [{ json: { topic_list: { topics: [
  {
    id: 999001,
    title: 'Need an n8n workflow to pull invoices out of email attachments',
    slug: 'need-an-n8n-workflow-to-pull-invoices-out-of-email-attachments',
    created_at: minutesAgo(12),
    posts_count: 1,
    pinned: false,
  },
  {
    id: 999002,
    title: 'Looking for help syncing HubSpot deals into Google Sheets',
    slug: 'looking-for-help-syncing-hubspot-deals-into-google-sheets',
    created_at: minutesAgo(4320),
    posts_count: 7,
    pinned: false,
  },
  {
    id: 999003,
    title: 'Read this before posting in Jobs',
    slug: 'read-this-before-posting-in-jobs',
    created_at: minutesAgo(525600),
    posts_count: 1,
    pinned: true,
  },
  {
    id: 999004,
    title: '[FOR HIRE] Senior n8n developer, 5 years experience, available now',
    slug: 'for-hire-senior-n8n-developer',
    created_at: minutesAgo(30),
    posts_count: 1,
    pinned: false,
  },
] } } }];

// Select new postings.
//
// Discourse hands back the whole category listing on every poll, so the job is
// working out which topics are genuinely new and which are the same thirty that
// were there ten minutes ago.
//
// Three things are dropped before anything reaches the phone:
//   - pinned topics, which are the category's own announcements, never a job
//   - [FOR HIRE] posts, which are other freelancers advertising, not buyers
//   - anything already notified, tracked in workflow static data
//
// And one behaviour that is easy to get wrong and expensive to discover late:
// on the very first run the seen-set is empty, so a naive diff treats all thirty
// existing topics as new and fires thirty notifications at once. The first run
// seeds the set and stays deliberately silent.

// ── the only line you need to change ────────────────────────────────────────
// An ntfy topic is effectively a password: anyone who knows the string can read
// your notifications. Pick something long and unguessable, and do not commit it.
const NTFY_TOPIC = 'CHANGE-ME-to-something-long-and-unguessable';
// ───────────────────────────────────────────────────────────────────────────

const SELF_PROMO = /\[?\s*for\s+hire\s*\]?|available for (hire|work)|open to work|looking for work|seeking (a )?(role|work|job)/i;
const TTL_MS = 90 * 24 * 60 * 60 * 1000;   // remember a topic for 90 days
const MAX_ENTRIES = 2000;
const GRACE_MS = 5 * 60 * 1000;            // absorbs poll jitter and clock skew

const store = $getWorkflowStaticData('global');
const firstRun = store.seenTopics === undefined;
store.seenTopics = store.seenTopics || {};

const now = Date.now();
const prevPollAt = store.lastPollAt;       // read BEFORE it is overwritten below
store.lastPollAt = now;                    // the canary watches this, not notifications

// Evict anything past its TTL, so the set cannot grow without limit.
for (const [id, ts] of Object.entries(store.seenTopics)) {
  if (now - ts > TTL_MS) delete store.seenTopics[id];
}

// "47727m old" means nothing at a glance. "33d old" does.
const humanAge = (mins) => {
  if (mins === null) return 'age unknown';
  if (mins < 90) return mins + 'm old';
  if (mins < 2880) return Math.round(mins / 60) + 'h old';
  return Math.round(mins / 1440) + 'd old';
};

const topics = [];
for (const item of $input.all()) {
  const list = item.json && item.json.topic_list && item.json.topic_list.topics;
  if (Array.isArray(list)) topics.push(...list);
}

const out = [];
for (const t of topics) {
  const id = String(t.id);
  if (store.seenTopics[id]) continue;

  // Marked seen before the filters, so a pinned or [FOR HIRE] topic is judged
  // once and never re-examined on every subsequent poll.
  store.seenTopics[id] = now;

  if (t.pinned || t.pinned_globally) continue;
  if (SELF_PROMO.test(t.title || '')) continue;
  if (firstRun) continue;

  const createdMs = Date.parse(t.created_at);
  const unknownDate = Number.isNaN(createdMs);
  const ageMinutes = unknownDate ? null : Math.round((now - createdMs) / 60000);

  // Speed is the only variable in this channel worth optimising: the measured
  // window for a reply that gets read is same-day, so age is the first thing
  // to know and it goes at the front of the notification.
  const freshness = ageMinutes === null ? 'unknown'
    : ageMinutes <= 60 ? 'fresh'
    : ageMinutes <= 1440 ? 'today'
    : 'stale';

  // Was this posted since the last time we looked?
  //
  // The diff alone cannot answer that. Discourse orders the listing by ACTIVITY,
  // so a month-old thread that collects a single new reply re-enters the top
  // thirty and is indistinguishable from a fresh post. That is how a 269-day-old
  // thread arrived as a full-priority alert on 15 Aug.
  //
  // Comparing against the PREVIOUS POLL rather than against a fixed age is also
  // the behaviour wanted when the machine has been asleep — and it does sleep:
  // the 14 Aug log has gaps of 82 and 151 minutes. If the last poll was 24 hours
  // ago, a post made 12 hours ago is genuinely new and must still arrive at full
  // priority. A flat "older than a day is stale" rule would silently swallow
  // precisely the posts a weekend of sleep produces.
  //
  // An unparseable date counts as new: an occasional wrong buzz is cheaper than
  // a silent drop.
  const isNew = unknownDate ? true
    : prevPollAt == null ? ageMinutes <= 1440
    : createdMs > prevPollAt - GRACE_MS;

  // Re-listings are still sent, at ntfy's `min` priority: they appear in the
  // notification list without a buzz. Dropping them outright would lose the one
  // case that matters — a buyer coming back to their own dead thread.
  const priority = !isNew ? 'min' : freshness === 'fresh' ? 'high' : 'default';

  out.push({ json: {
    topic_id: t.id,
    title: t.title,
    url: 'https://community.n8n.io/t/' + t.slug + '/' + t.id,
    created_at: t.created_at,
    age_minutes: ageMinutes,
    freshness,
    is_new: isNew,
    priority,
    tags: isNew ? 'briefcase' : 'mag',
    notify_title: isNew
      ? 'n8n jobs: ' + freshness + ' (' + humanAge(ageMinutes) + ')'
      : 'n8n jobs: re-listed (' + humanAge(ageMinutes) + ')',
    replies: Math.max(0, (t.posts_count == null ? 1 : t.posts_count) - 1),
    notify_url: 'https://ntfy.sh/' + NTFY_TOPIC,
    none_new: false,
  }});
}

// Hard cap: drop the oldest if the set has grown past the limit.
const ids = Object.keys(store.seenTopics);
if (ids.length > MAX_ENTRIES) {
  ids.sort((a, b) => store.seenTopics[a] - store.seenTopics[b])
     .slice(0, ids.length - MAX_ENTRIES)
     .forEach(k => delete store.seenTopics[k]);
}

// Always return something, so the quiet path is visible in the execution log
// rather than looking like the workflow silently did nothing.
return out.length ? out : [{ json: {
  none_new: true,
  first_run: firstRun,
  seeded: firstRun ? Object.keys(store.seenTopics).length : 0,
  checked_at: new Date(now).toISOString(),
} }];

// Record that the notification actually went out.
//
// Separate from the poll timestamp on purpose. Notifications are supposed to be
// rare — roughly two or three addressable posts a month — so silence here is
// normal and must never be treated as a fault.

const store = $getWorkflowStaticData('global');
store.lastNotifyAt = Date.now();
store.notifyCount = (store.notifyCount || 0) + 1;

return $input.all().map(item => ({ json: {
  ...item.json,
  notified_at: new Date(store.lastNotifyAt).toISOString(),
  notify_count_total: store.notifyCount,
} }));

// Dead letter queue.
//
// A notification that cannot be delivered is kept with its full payload and the
// real error, ready to be sent again once the far end is back. The alternative
// is finding out weeks later that the one job worth replying to was lost to a
// thirty-second outage.
//
// It also releases the topic from the seen-set, so the next poll re-detects it
// rather than treating it as already handled. That interaction is the one that
// is easy to get wrong: without it, a failed notification means the topic is
// silently never seen again.

const store = $getWorkflowStaticData('global');
store.dlq = store.dlq || [];

const out = [];
for (const item of $input.all()) {
  const payload = item.json || {};
  const topicId = payload.topic_id != null ? String(payload.topic_id) : null;

  if (topicId && store.seenTopics) delete store.seenTopics[topicId];

  const entry = {
    failed_at: new Date().toISOString(),
    error: (item.error && (item.error.message || item.error)) || payload.error || 'unknown error',
    topic_id: payload.topic_id ?? null,
    title: payload.title ?? null,
    url: payload.url ?? null,
    payload,
    replayable: true,
    fingerprint_released: Boolean(topicId),
  };

  store.dlq.push(entry);
  out.push({ json: entry });
}

return out;

// Canary.
//
// This watches whether the MONITOR is still running, not whether it has found
// anything. That distinction is the whole point: the board carries roughly two
// or three addressable posts a month, so weeks of no notifications is the
// expected state and alarming on it would cry wolf constantly.
//
// A poll that has not happened, on the other hand, means nobody is watching the
// one channel where arriving early is the only thing that matters.

const QUIET_HOURS = 3;   // 18 consecutive missed polls at a 10-minute interval

const store = $getWorkflowStaticData('global');
const last = store.lastPollAt ?? null;
const hoursSince = last === null ? null : (Date.now() - last) / 3600000;
const silent = last === null || hoursSince > QUIET_HOURS;

return [{ json: {
  checked_at: new Date().toISOString(),
  last_poll_at: last === null ? null : new Date(last).toISOString(),
  hours_since_last_poll: hoursSince === null ? null : Math.round(hoursSince * 10) / 10,
  last_notify_at: store.lastNotifyAt ? new Date(store.lastNotifyAt).toISOString() : null,
  notify_count_total: store.notifyCount || 0,
  dlq_depth: (store.dlq || []).length,
  silent,
  verdict: silent
    ? 'MONITOR HAS NOT POLLED IN ' + QUIET_HOURS + 'H — nobody is watching the board'
    : 'watching',
} }];
